@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldSaveOrderWhenProcessing() {
        var order = new Order(1L, "Laptop", 999.99);

        orderService.processOrder(order);

        // Verify save was called exactly once with this order
        verify(orderRepository).save(order);
        // Verify findById was never called
        verify(orderRepository, never()).findById(any());
    }

    @Test
    void shouldNotifyCustomerAfterOrderCreation() {
        var customerId = 42L;

        orderService.createOrder(customerId, "Mouse");

        verify(notificationService).sendEmail(customerId, "Order created");
    }
}

@ExtendWith(MockitoExtension.class)
class CustomerServiceTest {
    @Mock
    private CustomerRepository customerRepository;

    @Captor
    private ArgumentCaptor<Customer> customerCaptor;

    @InjectMocks
    private CustomerService customerService;

    @Test
    void shouldCreateCustomerWithCorrectFields() {
        var email = "alice@example.com";
        var name = "Alice Smith";

        customerService.registerNewCustomer(name, email);

        // Capture the Customer object passed to save()
        verify(customerRepository).save(customerCaptor.capture());
        Customer captured = customerCaptor.getValue();

        // Assert on individual fields of the captured object
        assertThat(captured.getName()).isEqualTo(name);
        assertThat(captured.getEmail()).isEqualTo(email);
        assertThat(captured.getCreatedAt()).isNotNull();
        assertThat(captured.isActive()).isTrue();
    }
}

@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock private TransactionManager txManager;
    @Mock private PaymentGateway gateway;
    @Mock private NotificationService notifier;

    @InjectMocks
    private PaymentService paymentService;

    @Test
    void shouldProcessPaymentInCorrectOrder() {
        var orderId = 123L;
        var amount = 99.99;

        paymentService.processPayment(orderId, amount);

        // Create InOrder verifier for multiple mocks
        InOrder inOrder = inOrder(txManager, gateway, notifier);

        // Verify calls happened in this exact sequence
        inOrder.verify(txManager).beginTransaction();
        inOrder.verify(gateway).charge(orderId, amount);
        inOrder.verify(txManager).commit();
        inOrder.verify(notifier).sendReceipt(orderId);

        // If notifier was called before commit, test fails
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock private OrderRepository orderRepository;
    @Mock private PaymentService paymentService;
    @Mock private EmailService emailService;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldNotSaveOrChargeWhenOrderIsInvalid() {
        var invalidOrder = new Order(null, "Laptop", -50.0);

        var result = orderService.processOrder(invalidOrder);

        assertThat(result.isSuccess()).isFalse();
        // Verify risky operations never happened
        verify(orderRepository, never()).save(any());
        verify(paymentService, never()).charge(any(), anyDouble());
    }

    @Test
    void shouldNotInteractWithEmailServiceOnDryRun() {
        orderService.validateOrder(new Order(1L, "Mouse", 25.0));

        // Assert email service was completely untouched
        verifyNoInteractions(emailService);
    }
}

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock private OrderRepository orderRepository;
    @Mock private PricingService pricingService;

    @Captor private ArgumentCaptor<Order> orderCaptor;

    @InjectMocks
    private OrderService orderService;

    @Test
    void shouldCreateOrderWithCorrectFieldsAndComputedTotal() {
        when(pricingService.calculateTotal(anyList())).thenReturn(199.98);

        var items = List.of("Laptop", "Mouse");
        var customerId = 42L;

        orderService.createOrder(customerId, items);

        verify(orderRepository).save(orderCaptor.capture());
        Order captured = orderCaptor.getValue();

        // Assert on individual fields of the captured entity
        assertThat(captured.getCustomerId()).isEqualTo(customerId);
        assertThat(captured.getItems()).containsExactly("Laptop", "Mouse");
        assertThat(captured.getTotalAmount()).isEqualTo(199.98);
        assertThat(captured.getCreatedAt()).isNotNull();
        assertThat(captured.getStatus()).isEqualTo(OrderStatus.PENDING);
    }
}
